        if (it.sub || it.desc) kids.push(h('span', { key: 'm', class: 'meta dim' }, it.sub || it.desc));
        kids.push(h('span', { key: 'a', class: 'ds-row-arrow' }, String(it.meta || 'open').toLowerCase()));
